package com.medibook.security;
import com.medibook.repository.UserRepository; import io.jsonwebtoken.Claims; import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter; import java.io.IOException; import java.util.List;
@Component public class JwtFilter extends OncePerRequestFilter {
 private final JwtService jwt; private final UserRepository users; public JwtFilter(JwtService jwt,UserRepository users){this.jwt=jwt;this.users=users;}
 @Override protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException{String header=req.getHeader("Authorization");if(header!=null&&header.startsWith("Bearer "))try{Claims c=jwt.parse(header.substring(7));var user=users.findByEmail(c.getSubject());if(user.isPresent()&&user.get().isActive()){var auth=new UsernamePasswordAuthenticationToken(user.get().getId(),null,List.of(new SimpleGrantedAuthority("ROLE_"+user.get().getRole().name())));SecurityContextHolder.getContext().setAuthentication(auth);}}catch(RuntimeException ignored){SecurityContextHolder.clearContext();}chain.doFilter(req,res);}
}
